INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(62434031, 'Sylvan Flowerknight', '森罗的花卉士 水仙', '森羅の花卉士 ナルサス', 'Effect Monster', 'Plant', 'EARTH', 4, 1800, 1000, '这张卡召唤成功时，可以把自己卡组最上面的卡翻开。翻开的卡是植物族怪兽的场合，那只怪兽送去墓地。不是的场合，那张卡回到卡组最下面。此外，卡组的这张卡被卡的效果翻开送去墓地的场合，可以从卡组选1张名字带有「森罗」的卡在卡组最上面放置。'),
(99429730, 'Sylvan Guardioak', '森罗的番人 橡树', '森羅の番人 オーク', 'Effect Monster', 'Plant', 'EARTH', 6, 2400, 1500, '1回合1次，自己的主要阶段时才能发动。从自己卡组上面把最多3张卡翻开。翻开的卡之中有植物族怪兽的场合，那些卡全部送去墓地。剩下的卡用喜欢的顺序回到卡组最下面。此外，卡组的这张卡被卡的效果翻开送去墓地的场合，可以从自己墓地选择这张卡以外的1只植物族怪兽回到卡组最上面。'),
(25824484, 'Sylvan Hermitree', '森罗的仙树 凤凰木', '森羅の仙樹 レギア', 'Effect Monster', 'Plant', 'FIRE', 8, 2700, 1800, '1回合1次，自己的主要阶段时才能发动。自己卡组最上面的卡翻开。翻开的卡是植物族怪兽的场合，那只怪兽送去墓地，从卡组抽1张卡。不是的场合，那张卡回到卡组最下面。此外，卡组的这张卡被卡的效果翻开送去墓地的场合，从自己卡组上面把最多3张卡确认，用喜欢的顺序回到卡组上面。'),
(99641328, 'Sylvan Komushroomo', '森罗的影孢子 伞菌', '森羅の影胞子 ストール', 'Effect Monster', 'Plant', 'FIRE', 2, 100, 2000, '这张卡反转时，可以从自己卡组上面把最多5张卡翻开。翻开的卡之中有植物族怪兽的场合，那些怪兽全部送去墓地。剩下的卡用喜欢的顺序回到卡组最下面。此外，卡组的这张卡被卡的效果翻开送去墓地的场合，可以选择场上1张魔法·陷阱卡破坏。'),
(73136204, 'Sylvan Lotuswain', '森罗的渡守 莲花', '森羅の渡し守 ロータス', 'Effect Monster', 'Plant', 'WATER', 5, 2300, 1100, '1回合1次，可以把对方场上的卡数量的卡从自己卡组上面翻开。翻开的卡之中有植物族怪兽的场合，那些怪兽全部送去墓地。剩下的卡用喜欢的顺序回到卡组最下面。此外，卡组的这张卡被卡的效果翻开送去墓地的场合，可以选择「森罗的渡守 莲花」以外的自己墓地最多5张名字带有「森罗」的卡用喜欢的顺序回到卡组下面。'),
(36046926, 'Sylvan Marshalleaf', '森罗的水先 叶子', '森羅の水先 リーフ', 'Effect Monster', 'Plant', 'WATER', 3, 1500, 1200, '这张卡召唤成功时，可以从自己卡组上面把最多2张卡翻开。翻开的卡之中有植物族怪兽的场合，那些怪兽全部送去墓地。剩下的卡用喜欢的顺序回到卡组最下面。此外，卡组的这张卡被卡的效果翻开送去墓地的场合，可以选择场上1只怪兽破坏。'),
(47077318, 'Sylvan Mikorange', '森罗的蜜柑子 柑橘', '森羅の蜜柑子 シトラ', 'Effect Monster', 'Plant', 'WATER', 3, 400, 1100, '①：场上的这张卡被对方破坏送去墓地时才能发动。自己卡组最上面的卡翻开，那张卡是植物族怪兽的场合，那只怪兽送去墓地。不是的场合，那张卡回到卡组最下面。 ②：卡组的这张卡被效果翻开送去墓地的场合发动。自己场上的全部植物族怪兽的攻击力·守备力上升300。'),
(63257623, 'Sylvan Peaskeeper', '森罗的监实者 豌豆', '森羅の実張り ピース', 'Effect Monster', 'Plant', 'WIND', 1, 400, 100, '这张卡召唤·特殊召唤成功时，可以把自己卡组最上面的卡翻开。翻开的卡是植物族怪兽的场合，那只怪兽送去墓地。不是的场合，那张卡回到卡组最下面。此外，卡组的这张卡被卡的效果翻开送去墓地的场合，可以从自己墓地选择1只4星以下的植物族怪兽特殊召唤。「森罗的监实者 豌豆」的这个效果1回合只能使用1次。'),
(33909817, 'Sylvan Princessprite', '森罗的姬芽宫', '森羅の姫芽宮', 'XYZ Monster', 'Plant', 'LIGHT', 1, 1800, 100, '1星怪兽×2 「森罗的姬芽宫」的①②的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除才能发动。自己卡组最上面的卡翻开。翻开的卡是魔法·陷阱卡的场合，那张卡加入手卡。不是的场合，那张卡送去墓地。 ②：从手卡以及这张卡以外的自己场上的表侧表示怪兽之中把1只植物族怪兽送去墓地，以自己墓地1只「森罗」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(20579538, 'Sylvan Princessprout', '森罗的姬芽君 幼芽', '森羅の姫芽君 スプラウト', 'Effect Monster', 'Plant', 'LIGHT', 1, 100, 100, '「森罗的姬芽君 幼芽」的①②的效果1回合各能使用1次。 ①：把这张卡解放才能发动。自己卡组最上面的卡翻开送去墓地。那之后，可以选自己墓地1只「幼芽」怪兽在自己卡组最上面放置。 ②：卡组的这张卡被效果翻开送去墓地的场合，宣言1～8的任意等级才能发动。这张卡从墓地特殊召唤，这张卡的等级变成宣言的等级。'),
(10530913, 'Sylvan Sagequoia', '森罗的贤树 舍曼将军树', '森羅の賢樹 シャーマン', 'Effect Monster', 'Plant', 'WIND', 7, 2600, 2100, '名字带有「森罗」的怪兽被送去墓地时，这张卡可以从手卡特殊召唤。1回合1次，自己的主要阶段时才能发动。自己卡组最上面的卡翻开。翻开的卡是植物族怪兽的场合，那只怪兽送去墓地。不是的场合，那张卡回到卡组最下面。此外，卡组的这张卡被卡的效果翻开送去墓地的场合，可以选择自己墓地1张名字带有「森罗」的魔法·陷阱卡加入手卡。'),
(47741109, 'Sylvan Snapdrassinagon', '森罗的隐蜜 金鱼草', '森羅の隠蜜 スナッフ', 'Effect Monster', 'Plant', 'DARK', 1, 900, 400, '手卡·场上的这张卡被送去墓地的场合，可以把自己卡组最上面的卡翻开。翻开的卡是植物族怪兽的场合，那只怪兽送去墓地。不是的场合，那张卡回到卡组最下面。此外，卡组的这张卡被卡的效果翻开送去墓地的场合，可以把自己卡组最上面的卡翻开。翻开的卡是植物族怪兽的场合，那只怪兽送去墓地。不是的场合，那张卡回到卡组最下面。'),
(49838105, 'Sylvan Waterslide', '森罗的泷滑', '森羅の滝滑り', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '每次对方怪兽直接攻击宣言，可以把这张卡的效果发动。自己卡组最上面的卡翻开。翻开的卡是植物族怪兽的场合，那只怪兽送去墓地。不是的场合，那张卡回到卡组最下面。此外，只要这张卡在场上存在，自己的抽卡阶段时作为进行通常抽卡的代替，自己卡组最上面的卡翻开。翻开的卡是植物族怪兽的场合，那只怪兽送去墓地。不是的场合，那张卡加入手卡。'),
(2295831, 'Symbol of Friendship', '拼图之圈', 'ピースの輪', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方场上有怪兽3只以上存在，自己场上没有卡存在的场合，自己抽卡阶段通过把通常抽卡的这张卡持续公开，那个回合的主要阶段1才能发动。自己从卡组选1张卡，给双方确认加入手卡。'),
(45305419, 'Symbol of Heritage', '继承之印', '継承の印', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '自己墓地有3张同名怪兽卡存在时发动。选择那些怪兽的其中1只在自己场上特殊召唤，并装备这张卡。这张卡破坏时，装备怪兽破坏。'),
(78794994, 'Symbols of Duty', '战线复活的代价', '戦線復活の代償', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '把自己场上1只通常怪兽送去墓地，选择自己或者对方的墓地1只怪兽才能发动。选择的怪兽在自己场上特殊召唤，把这张卡装备。这张卡从场上离开时，装备怪兽破坏。'),
(75304793, 'Symph Amplifire', '扩音器热焰', 'アンプリファイヤー', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，每次「音响战士」卡持有的效果发动给这张卡放置1个音响指示物。 ②：场上的「音响战士」怪兽的攻击力上升这张卡的音响指示物数量×100。 ③：1回合1次，可以把自己场上的音响指示物的以下数量取除，那个效果发动。 ●5个：给与对方为场上的「音响战士」卡数量×300伤害。 ●7个：选最多有场上的「音响战士」卡数量的对方的场上·墓地的卡除外。'),
(68933343, 'Symphonic Warrior Basses', '音响战士 贝西斯', '音響戦士ベーシス', 'Tuner Monster', 'Machine', 'WIND', 1, 600, 400, '①：1回合1次，以场上1只「音响战士」怪兽为对象才能发动。直到回合结束时，那只怪兽的等级上升手卡数量的数值。 ②：把墓地的这张卡除外，以自己场上1只「音响战士」怪兽为对象才能发动。直到回合结束时，那只自己的「音响战士」怪兽的等级上升手卡数量的数值。'),
(70204022, 'Symphonic Warrior DJJ', '音响战士 混音骑师', '音響戦士ディージェス', 'Pendulum Effect Monster', 'Machine', 'WIND', 4, 1200, 1200, '这个卡名的怪兽效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「音响战士 DJ调音台」以外的1只「音响战士」怪兽里侧守备表示特殊召唤。自己的场地区域有「音响放大器」存在的场合，可以作为代替从卡组把「音响战士 DJ调音台」以外的1只「音响战士」怪兽效果无效特殊召唤。'),
(94331452, 'Symphonic Warrior Drumss', '音响战士 爵师鼓', '音響戦士ドラムス', 'Tuner Monster', 'Machine', 'WIND', 2, 700, 700, '宣言1个属性，选择场上表侧表示存在的1只名字带有「音响战士」的怪兽发动。选择的怪兽变成宣言的属性。这个效果1回合只能使用1次。此外，宣言1个属性，可以把自己墓地存在的这张卡从游戏中除外，自己场上表侧表示存在的1只名字带有「音响战士」的怪兽变成宣言的属性。'),
(12525049, 'Symphonic Warrior Guitaar', '音响战士 吉伊他', '音響戦士ギータス', 'Pendulum Effect Monster', 'Machine', 'WIND', 3, 1500, 100, '①：这张卡召唤成功时，以自己墓地1只「音响战士」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(43210483, 'Symphonic Warrior Guitariss', '音响战士 副奏吉他', '音響戦士ギタリス', 'Pendulum Tuner Effect Monster', 'Machine', 'WIND', 3, 1100, 500, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：自己的场地区域有「音响放大器」存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合，以自己的灵摆区域1张卡为对象才能发动。那张卡回到持有者手卡。'),
(5399521, 'Symphonic Warrior Miccs', '音响战士 麦克疯', '音響戦士マイクス', 'Pendulum Effect Monster', 'Machine', 'WIND', 5, 2300, 1100, '①：这张卡可以把自己场上3个音响指示物取除，从手卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的回合，自己在通常召唤外加上只有1次，自己主要阶段可以把1只怪兽召唤。'),
(31826057, 'Symphonic Warrior Piaano', '音响战士 钢昂琴', '音響戦士ピアーノ', 'Tuner Monster', 'Machine', 'WIND', 3, 900, 1300, '宣言1个种族，选择场上表侧表示存在的1只名字带有「音响战士」的怪兽发动。选择的怪兽变成宣言的种族。这个效果1回合只能使用1次。此外，宣言1个种族，可以把自己墓地存在的这张卡从游戏中除外，自己场上表侧表示存在的1只名字带有「音响战士」的怪兽变成宣言的种族。'),
(24070330, 'Symphonic Warrior Rockks', '音响战士 摇滚乐队', '音響戦士ロックス', 'Synchro Pendulum Effect Monster', 'Machine', 'WIND', 7, 2500, 1500, '调整＋调整以外的怪兽1只以上 这个卡名的①②的怪兽效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。从自己的额外卡组把1只表侧表示的灵摆怪兽加入手卡。 ②：自己的场地区域有「音响放大器」存在的场合才能发动。选场上1张卡破坏。 ③：怪兽区域的这张卡被战斗·效果破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(49919798, 'Symphonic Warrior Synthess', '音响战士 合成乐师', '音響戦士サイザス', 'Flip Effect Monster', 'Machine', 'WIND', 4, 1200, 1900, '①：这张卡反转的场合才能发动。从卡组把「音响战士 合成器」以外的1只「音响战士」怪兽加入手卡。 ②：1回合1次，以「音响战士 合成器」以外的自己的场上·墓地1只「音响战士」怪兽为对象才能发动。这张卡直到结束阶段当作和那只怪兽同名卡使用，得到相同效果。 ③：把墓地的这张卡除外，以「音响战士 合成器」以外的除外的1只自己的「音响战士」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(75646173, 'Synchar', '法兰克斯', 'ファランクス', 'Normal Monster', 'Beast', 'EARTH', 3, 800, 900, '上下都有头的令人作呕的怪兽。从口中吐出激光。'),
(21879581, 'Synchro Barrier', '同调障壁', 'シンクロ・バリアー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上存在的1只同调怪兽解放发动。直到下个回合的结束阶段时，自己受到的全部伤害变成0。'),
(35537860, 'Synchro Blast Wave', '精神同调波', '精神同調波', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有同调怪兽表侧表示存在的场合才能发动。对方场上存在的1只怪兽破坏。'),
(98143165, 'Synchro Boost', '同调英雄', 'シンクロ・ヒーロー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：装备怪兽的等级上升1星，攻击力上升500。'),
(89974904, 'Synchro Call', '同调呼唤', 'シンクロコール', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只怪兽为对象才能发动。那只怪兽效果无效特殊召唤，只用包含那只怪兽的自己场上的怪兽为素材把1只龙族·恶魔族的暗属性同调怪兽同调召唤。'),
(36737092, 'Synchro Change', '同调变化', 'シンクロ・チェンジ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上表侧表示存在的1只同调怪兽从游戏中除外发动。和那只怪兽相同等级的1只同调怪兽从额外卡组特殊召唤。这个效果特殊召唤的效果怪兽的效果无效化。'),
(23442438, 'Synchro Chase', '同步追走', 'シンクロ・チェイス', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己把「战士」、「同调士」、「星尘」同调怪兽同调召唤的场合，以作为那次同调召唤的素材的自己墓地1只怪兽为对象才能发动。那只怪兽守备表示特殊召唤。 ②：只要这张卡在魔法与陷阱区域存在，对方不能对应原本卡名包含「战士」、「同调士」、「星尘」之内任意种的自己的同调怪兽的效果的发动把魔法·陷阱·怪兽的效果发动。'),
(88289295, 'Synchro Control', '同调控制', 'シンクロ・コントロール', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这张卡在自己场上以及自己墓地没有同调怪兽存在的场合才能发动。支付1000基本分，选择对方场上表侧表示存在的1只同调怪兽发动。直到自己的结束阶段时，得到选择的怪兽的控制权。'),
(41097056, 'Synchro Cracker', '同调破解', 'シンクロ・クラッカー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只同调怪兽为对象才能发动。那只怪兽回到持有者的额外卡组，持有那只同调怪兽的原本攻击力以下的攻击力的对方场上的表侧表示怪兽全部破坏。'),
(22414174, 'Synchro Creed', '同调贪欲', 'シンクロ・クリード', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：场上有同调怪兽存在的场合才能发动。自己抽1张。场上有同调怪兽3只以上存在的场合，再让自己可以抽1张。'),
(24545464, 'Synchro Deflector', '同调体反射', 'シンクロン・リフレクト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的同调怪兽成为攻击对象时才能发动。那个攻击无效，对方场上存在的1只怪兽破坏。'),
(47699948, 'Synchro Dilemma', '同步两难', 'シンクロ・ディレンマ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：可以从以下效果选择1个发动。 ●从手卡以及自己场上的表侧表示怪兽之中把1只「同调士」怪兽送去墓地才能发动。从手卡把1只怪兽特殊召唤。 ●以这张卡以外的自己场上1张卡为对象才能发动。那张卡破坏，从自己的手卡·墓地选原本卡名和那张卡不同的1只「同调士」怪兽特殊召唤。'),
(75105429, 'Synchro Ejection', '同调驱逐', 'シンクロ・イジェクション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择对方场上表侧表示存在的1只同调怪兽从游戏中除外，对方从卡组抽1张卡。'),
(43834302, 'Synchro Fellowship', '同步同伴', 'シンクロ・フェローズ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把以下怪兽各1只加入手卡。那之后，选自己1张手卡丢弃。 ●「废品同调士」 ●有「废品战士」「星尘龙」其中任意种的卡名记述的怪兽 ②：把墓地的这张卡除外，以自己场上1只同调怪兽为对象才能发动。那只怪兽的等级下降1星。并且再在这个回合让自己在通常召唤外加上只有1次，自己主要阶段可以把1只「同调士」怪兽召唤。'),
(50727844, 'Synchro Forceback', '同调推回', 'シンクロ・フォースバック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以最多有自己场上的同调怪兽种类数量的场上的怪兽为对象才能发动。那些怪兽回到手卡。'),
(15839054, 'Synchro Fusionist', '同步结融体', 'シンクロ・フュージョニスト', 'Effect Monster', 'Spellcaster', 'DARK', 2, 800, 600, '①：这张卡作为同调素材送去墓地的场合才能发动。从卡组把1张「融合」魔法卡加入手卡。'),
(52128900, 'Synchro Gift', '同调礼物', 'シンクロ・ギフト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只同调怪兽和1只同调怪兽以外的怪兽发动。直到这个回合的结束阶段时，选择的同调怪兽的攻击力变成0，另1只怪兽的攻击力上升那个原本攻击力数值。'),
(50702124, 'Synchro Magnet', '同调磁铁头', 'シンクロ・マグネーター', 'Tuner Monster', 'Machine', 'EARTH', 3, 1000, 600, '这张卡不能通常召唤。自己对同调怪兽的同调召唤成功时，这张卡可以从手卡特殊召唤。'),
(14507213, 'Synchro Material', '同调素材', 'シンクロ・マテリアル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择对方场上表侧表示存在的1只怪兽发动。这个回合自己同调召唤的场合，可以把选择的怪兽作为同调素材。这张卡发动的回合，自己不能进行战斗阶段。'),
(99243014, 'Synchro Overtake', '同步超车', 'シンクロ・オーバーテイク', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不是同调怪兽不能从额外卡组特殊召唤。 ①：把额外卡组1只同调怪兽给对方观看，从自己的卡组·墓地选那只怪兽有卡名记述的1只同调素材怪兽加入手卡或特殊召唤。'),
(653675, 'Synchro Overtop', '同步凌驾', 'シンクロ・オーバートップ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地的7·8星的龙族同调怪兽任意数量为对象才能发动。那些怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的等级变成1星，效果无效化。这个回合，自己不是同调怪兽不能从额外卡组特殊召唤。 ②：自己的同调怪兽被战斗破坏时，把墓地的这张卡除外才能发动。从额外卡组把1只「红龙」特殊召唤。'),
(83962752, 'Synchro Panic', '同调恐慌', 'シンクロ・パニック', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡发动后，第3次的自己准备阶段破坏。 ①：自己场上的表侧表示的同调怪兽被战斗或者对方的效果破坏的场合，以那之内的1只为对象才能把这张卡发动。等级合计直到变成和那只怪兽相同为止，从自己墓地把调整1只和调整以外的怪兽任意数量特殊召唤。这个效果特殊召唤的怪兽在这个回合不会被战斗·效果破坏。 ②：只要这张卡在魔法与陷阱区域存在，双方不能同调召唤。'),
(88901994, 'Synchro Rumble', '同步轰鸣', 'シンクロ・ランブル', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只调整或者1只7·8星的龙族同调怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这张卡的发动后，直到回合结束时自己不是同调怪兽不能从额外卡组特殊召唤。 ②：自己场上的「红龙」或者7·8星的龙族同调怪兽被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(79796561, 'Synchro Soldier', '同调炮手', 'シンクロ・ガンナー', 'Effect Monster', 'Machine', 'EARTH', 1, NULL, NULL, '1回合1次，自己的主要阶段1才能发动。把自己场上表侧表示存在的1只同调怪兽从游戏中除外并给与对方基本分600分伤害。这个效果除外的怪兽在下次的自己的准备阶段时回到场上。'),
(30123142, 'Synchro Strike', '同调合击', 'シンクロ・ストライク', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '同调召唤的1只怪兽的攻击力直到结束阶段时上升同调素材的怪兽数量×500的数值。'),
(57246528, 'Synchro Transcend', '同调超越', 'シンクロ・トランセンド', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以对方场上1只同调怪兽为对象才能发动。把持有比那只怪兽高1星的等级的1只同调怪兽从额外卡组特殊召唤。这个效果特殊召唤的怪兽在这个回合不能把效果发动。'),
(35817848, 'Synchro Transmission', '同步传送', 'シンクロ・トランスミッション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段才能发动。进行1只同调怪兽的同调召唤。 ②：自己主要阶段，把这个回合没有送去墓地的这张卡从墓地除外，以自己墓地1只同调怪兽为对象才能发动。那只怪兽回到额外卡组。那之后，自己抽1张。'),
(36742774, 'Synchro World', '同步世界', 'シンクロ・ワールド', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：每次怪兽同调召唤给这张卡放置2个信号指示物。 ②：可以把自己场上的信号指示物的以下数量取除，那个效果发动。 ●4：自己场上1只表侧表示怪兽的等级上升或下降1星。 ●7：从自己墓地把1只调整特殊召唤。 ●10：从自己墓地把1只同调怪兽特殊召唤。 ③：场上的这张卡被对方的效果破坏的场合才能发动。从额外卡组把1只「红龙」特殊召唤。'),
(60306277, 'Synchro Zone', '同步区域', 'シンクロ・ゾーン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，双方不用同调怪兽不能攻击宣言。 ②：调整以外的同调怪兽被战斗以外送去自己墓地的场合，以那之内的1只为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽当作调整使用。 ③：对方主要阶段，把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。进行1只同调怪兽的同调召唤。'),
(62125438, 'Synchron Carrier', '同步士运输者', 'シンクロン・キャリアー', 'Effect Monster', 'Machine', 'EARTH', 2, NULL, 1000, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把1只「同调士」怪兽召唤。 ②：这张卡在怪兽区域存在，其他的「同调士」怪兽作为战士族·机械族同调怪兽的同调素材送去自己墓地的场合才能发动。在自己场上把1只「同调士衍生物」（机械族·地·2星·攻1000/守0）特殊召唤。'),
(36643046, 'Synchron Explorer', '同步士探索者', 'シンクロン・エクスプローラー', 'Effect Monster', 'Machine', 'EARTH', 2, NULL, 700, '①：这张卡召唤成功时，以自己墓地1只「同调士」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(62125439, 'Synchron Token', '同步士运输者', 'シンクロン・キャリアー', 'Token', 'Machine', NULL, NULL, NULL, NULL, NULL),
(61032879, 'Synchronized Realm', '共有精神世界', 'コモンメンタルワールド', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '每次自己对同调怪兽的同调召唤成功，给与对方基本分500分伤害。'),
(77360173, 'Synkron Resonator', '同步克隆共鸣者', 'シンクローン・リゾネーター', 'Tuner Monster', 'Fiend', 'DARK', 1, 100, 100, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：场上有同调怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡从场上送去墓地的场合，以「同调克隆共鸣者」以外的自己墓地1只「共鸣者」怪兽为对象才能发动。那只怪兽加入手卡。'),
(72446038, 'Synthesis Spell', '合成魔术', '合成魔術', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「合成狼人」的降临需要。必须从场上或手卡把合计6星以上的卡作为祭品。'),
(16946849, 'Synthetic Seraphim', '人造天使', '人造天使', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，每次反击陷阱卡发动，在自己场上把1只「人造天使衍生物」（天使族·光·1星·攻/守300）特殊召唤。'),
(16946850, 'Synthetic Seraphim Token', '人造天使', '人造天使', 'Token', 'Fairy', NULL, NULL, NULL, NULL, NULL),
(18895832, 'System Down', '系统崩溃', 'システム・ダウン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '支付1000基本分。对方场上·墓地的机械族怪兽全部从游戏中除外。'),
(12927849, 'SZW - Fenrir Sword', '闪光异热同心武器-天圣辉狼剑', 'SZW－天聖輝狼剣', 'Effect Monster', 'Beast', 'LIGHT', 4, 1800, 1100, '这张卡召唤成功时，可以选择自己场上1只当作装备卡使用的名字带有「异热同心武器」的怪兽表侧守备表示特殊召唤。此外，自己的主要阶段时，手卡的这张卡可以当作装备卡使用给自己场上的名字带有「希望皇 霍普」的怪兽装备。装备怪兽战斗破坏对方怪兽送去墓地时，可以选择自己墓地1只名字带有「异热同心武器」的怪兽加入手卡。'),
(10456559, 'T.A.D.P.O.L.E.', '恶魂邪苦止', '悪魂邪苦止', 'Effect Monster', 'Aqua', 'WATER', 1, NULL, NULL, '自己场上存在的这张卡被战斗破坏送去墓地时，可以从自己卡组把「恶魂邪苦止」加入手卡。之后卡组洗切。'),
(54573517, 'T.G. All Clear', 'T.G.－全部就绪', 'TG－オールクリア', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：场上的「科技属」怪兽变成机械族。 ②：自己在通常召唤外加上只有1次，自己主要阶段可以把1只「科技属」怪兽召唤。 ③：自己主要阶段才能发动。自己的手卡·场上1只「科技属」怪兽破坏，和那只怪兽卡名不同的1只「科技属」怪兽从自己的卡组·墓地加入手卡。'),
(51447164, 'T.G. Blade Blaster', 'T.G.刀锋枪手', 'TG ブレード・ガンナー', 'Synchro Monster', 'Machine', 'EARTH', 10, 3300, 2200, '同调怪兽调整＋调整以外的同调怪兽1只以上 ①：场上的这张卡为对象的魔法·陷阱卡由对方发动时，把1张手卡送去墓地才能发动。那个效果无效。 ②：对方回合1次，从自己墓地把1只「科技属」怪兽除外才能发动。表侧表示的这张卡除外。 ③：这张卡的②的效果除外的场合，下次的准备阶段发动。除外状态的这张卡特殊召唤。'),
(48633301, 'T.G. Booster Raptor', 'T.G.助推盗龙', 'TG ブースター・ラプトル', 'Effect Monster', 'Dinosaur', 'WIND', 1, 400, 300, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：自己场上有「科技属」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：场上的这张卡被破坏送去墓地的回合的结束阶段才能发动。从卡组把「科技属 推进盗龙」以外的1只「科技属」怪兽加入手卡。'),
(64898834, 'T.G. Catapult Dragon', '科技属 弹射龙', 'TG カタパルト・ドラゴン', 'Effect Monster', 'Dragon', 'EARTH', 2, 900, 1300, '1回合1次，可以从手卡把1只3星以下的名字带有「科技属」的调整特殊召唤。'),
(2339825, 'T.G. Close', 'T.G.－闭锁', 'TG－クローズ', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上有机械族「科技属」怪兽存在，怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效并破坏。 ②：这张卡在墓地存在的状态，同调怪兽被除外的场合才能发动。这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(64910482, 'T.G. Cyber Magician', '科技属 电子化魔术师', 'TG サイバー・マジシャン', 'Tuner Monster', 'Spellcaster', 'LIGHT', 1, NULL, NULL, '把自己场上表侧表示存在的这张卡作为名字带有「科技属」的同调怪兽的同调素材的场合，可以把手卡的名字带有「科技属」的怪兽作为其他的调整以外的同调素材。场上存在的这张卡被破坏送去墓地的回合的结束阶段时，可以从自己卡组把「科技属 电子化魔术师」以外的1只名字带有「科技属」的怪兽加入手卡。'),
(30348744, 'T.G. Drill Fish', 'T.G.钻头鱼', 'TG ドリル・フィッシュ', 'Effect Monster', 'Fish', 'WATER', 1, 100, 800, '这个卡名的①③的效果1回合各能使用1次。 ①：自己场上的怪兽只有「科技属」怪兽的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡可以直接攻击。 ③：自己的「科技属」怪兽给与对方战斗伤害时，以对方场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(94350039, 'T.G. Gear Zombie', 'T.G.齿轮僵尸', 'TG ギア・ゾンビ', 'Tuner Monster', 'Zombie', 'DARK', 1, 600, NULL, '这个卡名的效果1回合只能使用1次。 ①：以自己场上1只「科技属」怪兽为对象才能发动。这张卡从手卡特殊召唤。那之后，作为对象的怪兽的攻击力下降1000。'),
(95973569, 'T.G. Glaive Blaster', 'T.G.长柄刀爆破手', 'TG グレイヴ・ブラスター', 'Synchro Monster', 'Machine', 'EARTH', 12, 4000, 4000, '同调怪兽调整＋调整以外的同调怪兽2只以上 这张卡不用同调召唤不能特殊召唤。 ①：自己·对方回合，以从额外卡组特殊召唤的场上1只怪兽为对象才能发动（这个效果在1回合中可以使用最多有作为这张卡的同调素材的除调整以外的同调怪兽数量的次数）。那只怪兽除外。 ②：1回合1次，怪兽被表侧除外的场合，以那之内的1只为对象才能发动。那只怪兽无视召唤条件在自己场上特殊召唤。'),
(97836203, 'T.G. Halberd Cannon', 'T.G.战戟炮手', 'TG ハルバード・キャノン', 'Synchro Monster', 'Machine', 'EARTH', 12, 4000, 4000, '同调怪兽调整＋调整以外的同调怪兽2只以上 这张卡不用同调召唤不能特殊召唤。 ①：1回合1次，自己或对方把怪兽召唤·反转召唤·特殊召唤之际才能发动。这张卡在场上表侧表示存在的场合，那个无效，那些怪兽破坏。 ②：这张卡从场上送去墓地时，以自己墓地1只「科技属」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(47027714, 'T.G. Halberd Cannon/Assault Mode', 'T.G.战戟炮手／爆裂', 'TG ハルバード・キャノン／バスター', 'Effect Monster', 'Machine', 'EARTH', 12, 4500, 4500, '这张卡不能通常召唤。「爆裂模式」的效果才能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：对方把怪兽召唤·反转召唤·特殊召唤之际才能发动。那个无效，那些怪兽以及对方场上的特殊召唤的怪兽全部除外。 ②：场上的这张卡被破坏时，以自己墓地1只「科技属 戟炮手」为对象才能发动。那只怪兽无视召唤条件特殊召唤。'),
(90953320, 'T.G. Hyper Librarian', 'T.G.超图书馆员', 'TG ハイパー・ライブラリアン', 'Synchro Monster', 'Spellcaster', 'DARK', 5, 2400, 1800, '调整＋调整以外的怪兽1只以上 ①：这张卡在怪兽区域存在的状态，自己或对方把同调怪兽同调召唤的场合发动。这张卡在场上表侧表示存在的场合，自己抽1张。'),
(37300735, 'T.G. Jet Falcon', '科技属 喷气猎鹰', 'TG ジェット・ファルコン', 'Tuner Monster', 'Winged Beast', 'WIND', 3, 1400, 1200, '这张卡作为同调召唤的素材送去墓地的场合，给与对方基本分500分伤害。'),
(28189908, 'T.G. Limiter Removal', 'T.G.－突破限制', 'TG－ブレイクリミッター', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：丢弃1张手卡才能发动。从卡组把2只「科技属」怪兽加入手卡（同名卡最多1张）。 ②：把墓地的这张卡除外，以自己墓地1只「科技属」怪兽为对象才能发动。那只怪兽回到卡组。自己场上有机械族「科技属」怪兽存在的场合，也能不回到卡组加入手卡。'),
(66733743, 'T.G. Metal Skeleton', '科技属 透明金属骨架', 'TG メタル・スケルトン', 'Effect Monster', 'Zombie', 'DARK', 2, 1100, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：场上的怪兽被战斗或者对方的效果破坏的场合才能发动。这张卡从手卡特殊召唤。 ②：自己场上的「科技属」怪兽被战斗·效果破坏的场合，可以作为代替把场上·墓地的这张卡除外。'),
(32480825, 'T.G. Mighty Striker', 'T.G.强力突击兵', 'TG マイティ・ストライカー', 'Synchro Tuner Monster', 'Warrior', 'EARTH', 2, 1800, NULL, '调整＋调整以外的怪兽1只 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。从卡组把1张「科技属」魔法·陷阱卡加入手卡。 ②：对方主要阶段才能发动1次。用包含这张卡的自己场上的怪兽为素材进行同调召唤。 ③：这张卡从怪兽区域送去墓地的场合才能发动。从卡组把1张「科技属」卡送去墓地。'),
(68989420, 'T.G. Over Dragonar', 'T.G.超越龙兵', 'TG オーバー・ドラグナー', 'Synchro Monster', 'Dragon', 'DARK', 5, 2100, 1900, '调整＋调整以外的怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡同调召唤的场合才能发动。从自己墓地把「科技属」怪兽任意数量守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不是「科技属」怪兽不能特殊召唤。 ②：场上的这张卡被破坏的场合发动。自己抽1张。'),
(24943456, 'T.G. Power Gladiator', 'T.G.力量角斗士', 'TG パワー・グラディエイター', 'Synchro Monster', 'Warrior', 'EARTH', 5, 2300, 1000, '调整＋调整以外的名字带有「科技属」的怪兽1只以上 这张卡向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。场上存在的这张卡被破坏时，从自己卡组抽1张卡。'),
(62560742, 'T.G. Recipro Dragonfly', 'T.G.往复蜻蜓', 'TG レシプロ・ドラゴン・フライ', 'Synchro Monster', 'Insect', 'WIND', 2, 300, 300, '调整＋调整以外的怪兽1只 ①：1回合1次，以自己场上1只其他的「科技属」同调怪兽为对象才能发动。那只怪兽送去墓地。那之后，若作为送去墓地的那只怪兽的同调召唤的素材用过的一组怪兽全部是同调怪兽并在自己墓地齐集，可以把那一组特殊召唤。'),
(77392987, 'T.G. Rocket Salamander', 'T.G.火箭沙罗曼蛇', 'TG ロケット・サラマンダー', 'Effect Monster', 'Pyro', 'FIRE', 1, 600, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只「科技属」怪兽解放才能发动。原本卡名和解放的怪兽不同的1只「科技属」怪兽从卡组特殊召唤。 ②：自己场上有机械族「科技属」怪兽存在的场合，以自己墓地1只4星以下的「科技属」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(36687247, 'T.G. Rush Rhino', '科技属 突冲犀牛', 'TG ラッシュ・ライノ', 'Effect Monster', 'Beast', 'EARTH', 4, 1600, 800, '这张卡攻击的场合，伤害步骤内这张卡的攻击力上升400。场上存在的这张卡被破坏送去墓地的回合的结束阶段时，可以从自己卡组把「科技属 突冲犀牛」以外的1只名字带有「科技属」的怪兽加入手卡。'),
(11234702, 'T.G. Screw Serpent', 'T.G.螺旋桨海蛇', 'TG スクリュー・サーペント', 'Tuner Monster', 'Sea Serpent', 'WATER', 4, 1300, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合，以除「科技属 螺旋桨蛇」外的自己墓地1只4星以下的「科技属」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。 ②：把墓地的这张卡除外，以自己场上1只「科技属」怪兽为对象才能发动。那只怪兽的等级直到回合结束时上升或下降1星。'),
(99937842, 'T.G. Star Guardian', 'T.G.星之守护者', 'TG スター・ガーディアン', 'Synchro Tuner Monster', 'Warrior', 'LIGHT', 5, 100, 2200, '调整＋调整以外的「科技属」怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合，以自己墓地1只「科技属」怪兽为对象才能发动。那只怪兽加入手卡。 ②：自己主要阶段才能发动。从手卡把1只「科技属」怪兽特殊召唤。 ③：对方主要阶段才能发动（同一连锁上最多1次）。用包含这张卡的自己场上的怪兽为素材进行同调召唤。'),
(1315120, 'T.G. Striker', 'T.G.突击兵', 'TG ストライカー', 'Tuner Monster', 'Warrior', 'EARTH', 2, 800, NULL, '①：只有对方场上才有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：场上的这张卡被破坏送去墓地的回合的结束阶段才能发动。从卡组把「科技属 突击兵」以外的1只「科技属」怪兽加入手卡。'),
(74627016, 'T.G. Tank Grub', 'T.G.坦克幼虫', 'TG タンク・ラーヴァ', 'Tuner Monster', 'Insect', 'EARTH', 1, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：把自己场上的这张卡作为「科技属」同调怪兽的同调素材的场合，可以把这张卡当作调整以外的怪兽使用。 ②：这张卡作为「科技属」同调怪兽的同调素材送去墓地的场合才能发动。在自己场上把1只「科技属衍生物」（机械族·地·1星·攻/守0）攻击表示特殊召唤。'),
(50750868, 'T.G. Trident Launcher', 'T.G.三叉戟发射器', 'TG トライデント・ランチャー', 'Link Monster', 'Machine', 'EARTH', NULL, 2200, NULL, '包含「科技属」调整的效果怪兽2只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡连接召唤的场合才能发动。从自己的手卡·卡组·墓地各把1只「科技属」怪兽在作为这张卡所连接区的自己场上守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不是「科技属」怪兽不能特殊召唤。 ②：对方不能把这张卡所连接区的「科技属」同调怪兽作为效果的对象。'),
(293542, 'T.G. Warwolf', 'T.G.狼人', 'TG ワーウルフ', 'Effect Monster', 'Beast-Warrior', 'DARK', 3, 1200, NULL, '①：4星以下的怪兽特殊召唤时才能发动。这张卡从手卡特殊召唤。 ②：场上的这张卡被破坏送去墓地的回合的结束阶段才能发动。从卡组把「科技属 狼人」以外的1只「科技属」怪兽加入手卡。'),
(98558751, 'T.G. Wonder Magician', 'T.G.奇妙魔术师', 'TG ワンダー・マジシャン', 'Synchro Tuner Monster', 'Spellcaster', 'LIGHT', 5, 1900, NULL, '调整＋调整以外的「科技属」怪兽1只以上 ①：这张卡同调召唤的场合，以场上1张魔法·陷阱卡为对象发动。那张卡破坏。 ②：对方主要阶段才能发动（同一连锁上最多1次）。用包含这张卡的自己场上的怪兽为素材进行同调召唤。 ③：场上的这张卡被破坏的场合发动。自己抽1张。'),
(86449372, 'TA.I. Strike', '-艾-打成平手', 'Ai打ち', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己和对方的怪兽之间进行战斗的伤害计算时才能发动。那只自己怪兽的攻击力只在那次伤害计算时变成和那只对方怪兽的攻击力相同，那次伤害步骤结束时那次战斗破坏的怪兽的控制者受到那原本攻击力数值的伤害。 ②：自己的「@火灵天星」怪兽被战斗破坏的场合，可以作为代替把墓地的这张卡除外。'),
(59650656, 'Tachyon Chaos Hole', '快子时空混沌空洞', '時空混沌渦', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的「银河」超量怪兽被对方怪兽的攻击或者对方的效果破坏送去墓地时才能发动。对方场上的表侧表示的卡全部破坏并除外。 ②：这张卡在墓地存在的场合，自己抽卡阶段作为进行通常抽卡的代替，把墓地的这张卡除外，以自己墓地1只「银河」超量怪兽为对象才能发动。那只怪兽特殊召唤。'),
(72705654, 'Tachyon Cloudragon', '时空云笼', '時空の雲篭', 'Effect Monster', 'Dragon', 'LIGHT', 4, 300, 250, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡用抽卡以外的方法加入手卡的场合才能发动。这张卡特殊召唤。 ②：把这张卡解放才能发动。从自己的卡组·墓地把「时空云笼」以外的1只「时空」怪兽特殊召唤。 ③：这张卡在手卡·墓地存在，自己把龙族超量怪兽特殊召唤的场合，以那之内的1只为对象才能发动。把这张卡作为那只怪兽的超量素材。'),
(89789152, 'Tachyon Spiral Galaxy', '快子时空银河螺旋', 'タキオン・ギャラクシースパイラル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。自己场上有「银河眼时空龙」怪兽存在的场合，这张卡的发动从手卡也能用。 ①：以自己场上1只龙族「银河」怪兽为对象才能发动。那只表侧表示怪兽直到回合结束时不会被战斗破坏，不受自身以外的卡的效果影响。'),
(71083002, 'Tachyon Spiral of Destruction', '歼灭的快子时空螺旋', '殲滅のタキオン・スパイラル', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●自己场上有「银河」超量怪兽存在的场合才能发动。效果被无效化的对方场上的表侧表示卡全部破坏。 ●以「歼灭之时空螺旋」以外的自己墓地1张「时空」卡为对象才能发动。那张卡加入手卡。 ●以自己墓地1只龙族「No.」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(8038143, 'Tachyon Transmigration', '快子时空转生', 'タキオン・トランスミグレイション', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '自己场上有「银河眼时空龙」怪兽存在的场合，这张卡的发动从手卡也能用。 ①：自己场上有「银河眼」怪兽存在的场合，连锁2以后才能发动。这张卡的发动时积累的连锁上的全部对方的怪兽的效果·魔法·陷阱卡的发动无效，用这个效果把发动无效的卡在场上存在的场合，那些全部回到卡组。'),
(12467005, 'Tackle Crusader', '拦截十字军', 'タックルセイダー', 'Effect Monster', 'Rock', 'EARTH', 4, 1500, 1800, '这张卡被送去墓地的场合，可以从以下效果选择1个发动。 ●选择对方场上表侧表示存在的1只怪兽变成里侧守备表示。 ●选择对方场上表侧表示存在的1张魔法·陷阱卡回到持有者手卡。这个回合，对方不能把这个效果回到手卡的卡以及那些同名卡发动。'),
(89698120, 'Tactical Espionage Expert', '华丽的潜入工作员', '華麗なる潜入工作員', 'Effect Monster', 'Warrior', 'EARTH', 3, 1300, 1200, '这张卡召唤成功时，陷阱卡不能发动。'),
(58421530, 'Tactical Exchanger', '战术换膛室', 'タクティカル・エクスチェンバー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽破坏，从自己的卡组·墓地选原本卡名和那只怪兽不同的1只「弹丸」怪兽特殊召唤。'),
(16968936, 'Tactical Trainer of the Six Samurai', '六武众之指南番', '六武衆の指南番', 'Tuner Monster', 'Warrior', 'EARTH', 2, 200, 1200, '这个卡名的①的方法的特殊召唤1回合只能有1次，②③的效果1回合各能使用1次。 ①：自己场上有「六武众的指南番」以外的「六武众」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡从场上送去墓地的场合才能发动。从自己的卡组·墓地把1张「六武式」卡加入手卡。 ③：这张卡为素材作同调召唤的「六武众」怪兽得到以下效果。 ●对方场上的怪兽的攻击力下降500。'),
(83682725, 'Tail Swipe', '摆尾攻击', 'テールスイング', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只5星以上的恐龙族怪兽发动。选择对方场上存在的合计最多2只里侧表示怪兽或者比选择的恐龙族怪兽的等级低的怪兽回到持有者手卡。'),
(43641473, 'Tailor of the Fickle', '善变的裁缝师', '移り気な仕立屋', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把怪兽装备的1张装备卡，转换给1只别的能变成正确对象的怪兽。'),
(1187243, 'Tailwind of Gusto', '给薰风的追风', 'ガスタへの追風', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「薰风」怪兽才能装备。这个卡名的②③的效果1回合各能使用1次。 ①：装备怪兽不会被对方的效果破坏。 ②：可以把装备怪兽的等级·阶级的以下效果发动。 ●4以下：和装备怪兽种族不同的1只「薰风」怪兽从卡组特殊召唤。 ●5以上：从卡组把1只1星调整特殊召唤。 ③：把墓地的这张卡除外，从手卡丢弃1只风属性怪兽才能发动。从卡组把1张「薰风」魔法·陷阱卡加入手卡。'),
(50281477, 'Tainted of the Tistina', '提斯蒂娜的瘴神', 'ティスティナの瘴神', 'Effect Monster', 'Aqua', 'DARK', 5, 2000, NULL, '这张卡可以把对方场上1只里侧表示怪兽解放表侧表示上级召唤。 ①：通常召唤的这张卡的等级变成10星。 ②：这张卡从场上以外送去墓地的场合，以自己场上1只「提斯蒂娜」怪兽为对象才能发动。这个回合，自己只能用1只怪兽攻击，作为对象的怪兽在同1次的战斗阶段中可以作2次攻击。'),
(28725004, 'Tainted Wisdom', '恶魔的智慧', '悪魔の知恵', 'Effect Monster', 'Fiend', 'DARK', 3, 1250, 800, '这张卡的表示形式从攻击表示变成守备表示时，洗自己的卡组。'),
(44073668, 'Takriminos', '塔库利米诺斯', 'タクリミノス', 'Normal Monster', 'Sea Serpent', 'WATER', 4, 1500, 1200, '身体有鳍，在水中也能自由活动的海龙同类。'),
(3170832, 'Takuhee', '橐蜚', 'タクヒ', 'Normal Monster', 'Winged Beast', 'WIND', 4, 1450, 1000, '这鸟出现的时候，就是什么不幸之事发生前的征兆。'),
(80190753, 'Talaya, Princess of Cherry Blossoms', '樱姬 塔利亚', '桜姫タレイア', 'Effect Monster', 'Plant', 'WATER', 8, 2800, 1200, '①：这张卡的攻击力上升自己场上的植物族怪兽数量×100。 ②：只要这张卡在怪兽区域存在，这张卡以外的场上的植物族怪兽不会被效果破坏。'),
(82119326, 'Tales of Fairy Tail', NULL, NULL, 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, NULL),
(99289828, 'Tales of the White Forest', '白森之异闻', '白き森のいいつたえ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有幻想魔族或魔法师族的怪兽存在的场合才能发动。从卡组把1只「白森林」怪兽加入手卡。 ②：这张卡为让怪兽的效果发动而被送去墓地的场合才能发动。这张卡在自己场上盖放。'),
(71983925, 'Talisman of Spell Sealing', '魔法封印咒符', '魔法封印の呪符', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡仅当自己场上存在「封印师 明晴」时才能发动。这张卡在场上存在时，魔法卡不能发动，场上所有魔法卡的效果无效化。「封印师 明晴」不在自己场上存在时，这张卡破坏。'),
(19312169, 'Talisman of Trap Sealing', '陷阱封印咒符', '罠封印の呪符', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡仅当自己场上存在「封印师 明晴」时才能发动。这张卡在场上存在时，陷阱卡不能发动，场上所有陷阱卡的效果无效化。「封印师 明晴」不在自己场上存在时，这张卡破坏。'),
(96380700, 'Talkback Lancer', '答语枪兵', 'トークバック・ランサー', 'Link Monster', 'Cyberse', 'DARK', NULL, 1200, NULL, '2星以下的电子界族怪兽1只 这个卡名的效果1回合只能使用1次。 ①：把这张卡以外的自己场上1只电子界族怪兽解放，以原本卡名和那只怪兽不同的自己墓地1只「码语者」怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上特殊召唤。'),
(9175957, 'Tally-ho! Springans', '发现目标！守宝团！', 'タリホー！スプリガンズ！', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。这张卡也能把自己场上最多3个超量素材取除来发动。 ①：从卡组把1只「护宝炮妖」怪兽加入手卡。把超量素材取除来把这张卡发动的场合，可以再从自己的手卡·墓地把那个数量的「护宝炮妖」怪兽特殊召唤。 ②：自己主要阶段有这张卡在墓地存在的场合，以场上1只超量怪兽为对象才能发动。那只怪兽1个超量素材取除，这张卡加入手卡。'),
(74150658, 'Talons of Shurilane', '纹影之钩爪', 'タロンズ・オブ・シュリーレン', 'Effect Monster', 'Illusion', 'LIGHT', 6, 2100, 2050, '这个卡名的①③的效果1回合各能使用1次。 ①：对方回合，以「纹影魔爪」以外的自己场上1只恶魔族·幻想魔族怪兽为对象才能发动。那只怪兽回到手卡，这张卡从手卡特殊召唤。 ②：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。 ③：自己的卡为对象的效果由对方发动时，以对方场上1只怪兽为对象才能发动。场上的这张卡回到手卡，那只怪兽破坏。'),
(79757784, 'Tamtam the Melodious Diva', '幻奏音女 唐唐', '幻奏の音女タムタム', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1000, 2000, '①：自己场上有「幻奏」怪兽存在，这张卡特殊召唤成功的场合才能发动。从自己的卡组·墓地选1张「融合」加入手卡。 ②：这张卡成为融合召唤的素材送去墓地的场合，以自己场上1只「幻奏」怪兽为对象才能发动。那只怪兽的攻击力下降500，给与对方500伤害。'),
(14677495, 'Tanngnjostr of the Nordic Beasts', '极星兽 坦格乔斯特', '極星獣タングニョースト', 'Effect Monster', 'Beast', 'EARTH', 3, 800, 1100, '自己场上存在的怪兽被战斗破坏送去墓地时，这张卡可以从手卡特殊召唤。1回合1次，场上守备表示存在的这张卡变成表侧攻击表示时，可以从自己卡组把「极星兽 坦格乔斯特」以外的1只名字带有「极星兽」的怪兽表侧守备表示特殊召唤。'),
(15394083, 'Tanngrisnir of the Nordic Beasts', '极星兽 坦格里斯尼尔', '極星獣タングリスニ', 'Effect Monster', 'Beast', 'EARTH', 3, 1200, 800, '①：这张卡被战斗破坏送去墓地的场合发动。在自己场上把2只「极星兽衍生物」（兽族·地·3星·攻/守0）特殊召唤。'),
(9831539, 'Tannhauser Gate', '唐怀瑟之门', 'タンホイザーゲート', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上2只攻击力1000以下的相同种族的怪兽才能发动。选择的2只怪兽变成那2只的等级合计的等级。'),
(7020743, 'Tantrum Toddler', '凶孩子', '怒小児様', 'XYZ Monster', 'Beast', 'FIRE', 1, NULL, NULL, '1星怪兽×2 ①：卡的效果的发动无效的场合才能发动（同一连锁上最多1次）。把自己以及对方的墓地的卡各最多1张作为这张卡的超量素材。 ②：这张卡持有的超量素材数量让这张卡得到以下效果。 ●1个以上：这张卡的攻击力·守备力上升这张卡的超量素材数量×700。 ●4个以上：这张卡不会被战斗·效果破坏。 ●8个以上：自己·对方回合，把这张卡4个超量素材取除才能发动。场上的卡全部破坏。'),
(45016904, 'Tao Tao the Chanter', '阴阳师 道道', '陰陽師 タオタオ', 'Tuner Monster', 'Illusion', 'EARTH', 2, 900, 600, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。 ②：自己因战斗·效果受到伤害的场合才能发动。从自己的手卡·墓地把1只3星以上的幻想魔族怪兽特殊召唤。受到的伤害是2000以上的场合，也能从卡组·额外卡组选特殊召唤的怪兽。'),
(46247516, 'Tao the Chanter', '阴阳师 道', '陰陽師 タオ', 'Normal Monster', 'Spellcaster', 'EARTH', 3, 1200, 900, '侵蚀阴与阳的力量、产生出邪恶力量的魔导师。'),
(82566662, 'Taotie Dragon', '饕餮龙', 'トウテツドラゴン', 'Link Monster', 'Wyrm', 'DARK', NULL, 2500, NULL, '从额外卡组特殊召唤的怪兽2只以上 ①：这张卡得到作为这张卡的连接素材的怪兽种类的以下效果。 ●融合：战斗阶段中对方不能把怪兽的效果发动。 ●同调：自己主要阶段中对方不能把魔法·陷阱卡的效果发动。 ●超量：自己的主要阶段以及战斗阶段中对方不能把墓地的卡的效果发动。'),
(99946920, 'Taotie, Shadow of the Yang Zing', '魔龙星－饕餮', '魔竜星－トウテツ', 'Effect Monster', 'Wyrm', 'DARK', 5, 2200, NULL, '「魔龙星-饕餮」的①的效果1回合只能使用1次。 ①：自己场上的这张卡被战斗·效果破坏送去墓地时才能发动。从卡组把「魔龙星-饕餮」以外的1只「龙星」怪兽守备表示特殊召唤。 ②：1回合1次，对方的主要阶段以及战斗阶段才能发动。只用自己场上的「龙星」怪兽为同调素材作同调召唤。 ③：这张卡为同调素材的同调怪兽不能把控制权变更。'),
(8152834, 'Tarai', '陀螺威盥', '陀羅威', 'Effect Monster', 'Fairy', 'EARTH', 4, NULL, NULL, '这个卡名的效果1回合只能使用1次。 ①：这张卡在手卡存在的场合，以这个回合有在场上把效果发动过的自己·对方的主要怪兽区域1只表侧表示怪兽为对象才能发动。那只怪兽破坏，这张卡在那只怪兽存在过的区域特殊召唤。'),
(64892035, 'Tardy Orc', '过迟的兽人', '遅すぎたオーク', 'Effect Monster', 'Fiend', 'DARK', 4, 2200, NULL, '这张卡在召唤的回合不能攻击。'),
(86039057, 'Tasuke Knight', '帮一把骑士', 'タスケナイト', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1700, 100, '这张卡在墓地存在，自己手卡是0张的场合，对方怪兽的攻击宣言时才能发动。这张卡从墓地特殊召唤，战斗阶段结束。「帮一把骑士」的效果在决斗中只能使用1次。'),
(18444902, 'Tatakawa Knight', '打一仗骑士', 'タタカワナイト', 'Effect Monster', 'Warrior', 'EARTH', 4, 1500, NULL, '对方的卡的效果让自己的魔法·陷阱卡的发动无效的场合，把这张卡从手卡送去墓地才能发动。给与对方基本分1500分伤害。'),
(3096468, 'Tatsunecro', '尸龙子', 'タツネクロ', 'Tuner Monster', 'Zombie', 'DARK', 3, 500, 1700, '通常召唤的这张卡为素材作同调召唤的场合，手卡1只怪兽也能作为同调素材。那个时候的同调素材怪兽不去墓地而除外。 ①：只要这张卡在怪兽区域存在，自己不是不死族怪兽不能特殊召唤。'),
(55863245, 'Tatsunoko', '龙之子', 'たつのこ', 'Synchro Tuner Monster', 'Wyrm', 'WATER', 3, 1700, 500, '调整＋调整以外的怪兽1只以上 同调召唤的这张卡为素材作同调召唤的场合，手卡1只怪兽也能作为同调素材。 ①：这张卡只要在怪兽区域存在，不受其他怪兽的效果影响。'),
(47922711, 'Tatsunootoshigo', '海马', 'シーホース', 'Normal Monster', 'Beast', 'EARTH', 5, 1350, 1600, '半马半鱼的怪兽。以风一般的速度在海中奔驰。'),
(90740329, 'Taunt', '挑衅', '挑発', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方回合的主要阶段一，选择自己场上的1只怪兽才能发动。只要选择怪兽在场上存在，对方这个回合攻击的场合，必须以选择的怪兽为攻击对象。'),
(33779875, 'Teardrop the Rikka Queen', '六花圣泪滴花束', '六花聖ティアドロップ', 'XYZ Monster', 'Plant', 'WATER', 8, 2800, 2800, '8星怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：把这张卡1个超量素材取除，以自己·对方场上1只怪兽为对象才能发动。那只怪兽解放。这张卡有植物族怪兽在作为超量素材的场合，这个效果在对方回合也能发动。 ②：每次怪兽被解放发动。这张卡的攻击力直到回合结束时上升解放的怪兽数量×200。'),
(1329620, 'Tearlaments Cryme', '泪冠哀歌・响彻的叛乱残叫', '壱世壊に澄み渡る残響', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上有「珠泪哀歌族」怪兽或者「维萨斯-斯塔弗罗斯特」存在，怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效，那张卡回到持有者卡组。那之后，从自己手卡选1只怪兽送去墓地。 ②：这张卡被效果送去墓地的场合，以除外的1只自己的「珠泪哀歌族」怪兽为对象才能发动。那只怪兽加入手卡。'),
(33878367, 'Tearlaments Grief', '泪冠哀歌・回荡的丧恸反响', '壱世壊に渦巻く反響', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从自己的卡组·墓地选1只「珠泪哀歌族」怪兽或者「维萨斯-斯塔弗罗斯特」特殊召唤。那之后，选种族或者属性和这个效果特殊召唤的怪兽相同的自己场上1只怪兽送去墓地。 ②：这张卡被效果送去墓地的场合，以除外的1张自己的「珠泪哀歌族」陷阱卡为对象才能发动。那张卡加入手卡。'),
(37961969, 'Tearlaments Havnis', '泪冠哀歌・哈弗妮丝', 'ティアラメンツ・ハゥフニス', 'Effect Monster', 'Aqua', 'DARK', 3, 1600, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：对方把场上的怪兽的效果发动时才能发动。这张卡从手卡特殊召唤，从自己卡组上面把3张卡送去墓地。 ②：这张卡被效果送去墓地的场合才能发动。融合怪兽卡决定的包含墓地的这张卡的融合素材怪兽从自己的手卡·场上·墓地用喜欢的顺序回到持有者卡组下面，把那1只融合怪兽从额外卡组融合召唤。'),
(60362066, 'Tearlaments Heartbeat', '泪冠哀歌・震撼的鼓动心音', '壱世壊を揺るがす鼓動', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以场上1张魔法·陷阱卡为对象才能发动。那张卡回到持有者卡组。那之后，选自己1张手卡送去墓地。自己场上有「维萨斯-斯塔弗罗斯特」存在的场合，这个效果的对象可以变成2张。 ②：这张卡被效果送去墓地的场合，以自己墓地1张「珠泪哀歌族」陷阱卡为对象才能发动。那张卡加入手卡。'),
(28226490, 'Tearlaments Kaleido-Heart', '泪冠哀歌・卡雷多哈忒', 'ティアラメンツ・カレイドハート', 'Fusion Monster', 'Fiend', 'DARK', 9, 3000, 3000, '「珠泪哀歌族·雷诺哈特」＋水族怪兽×2 这张卡不能作为融合素材。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合或者这张卡在场上存在的状态有水族怪兽被效果送去自己墓地的场合，以对方场上1张卡为对象才能发动。那张卡回到持有者卡组。 ②：这张卡被效果送去墓地的场合才能发动。这张卡特殊召唤，从卡组把1张「珠泪哀歌族」卡送去墓地。'),
(4928565, 'Tearlaments Kashtira', '泪冠哀歌・怒刹帝利', 'ティアラメンツ・クシャトリラ', 'Effect Monster', 'Psychic', 'WATER', 7, 2300, 1200, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己·对方的主要阶段才能发动。这张卡从手卡特殊召唤，从自己的手卡·墓地选1张「俱舍怒威族」卡或者「珠泪哀歌族」卡除外。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从自己或者对方的卡组上面把3张卡送去墓地。 ③：这张卡被效果送去墓地的场合才能发动。从自己卡组上面把2张卡送去墓地。'),
(92731385, 'Tearlaments Kitkallos', '泪冠哀歌・琪多卡洛斯', 'ティアラメンツ・キトカロス', 'Fusion Monster', 'Aqua', 'DARK', 5, 2300, 1200, '「珠泪哀歌族」怪兽＋水族怪兽 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。从卡组选1张「珠泪哀歌族」卡加入手卡或送去墓地。 ②：以自己场上1只怪兽为对象才能发动。从自己的手卡·墓地选1只「珠泪哀歌族」怪兽特殊召唤，作为对象的怪兽送去墓地。 ③：这张卡被效果送去墓地的场合才能发动。从自己卡组上面把5张卡送去墓地。'),
(74078255, 'Tearlaments Merrli', '泪冠哀歌・梅露', 'ティアラメンツ・メイルゥ', 'Effect Monster', 'Aqua', 'DARK', 2, 800, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从自己卡组上面把3张卡送去墓地。 ②：这张卡被效果送去墓地的场合才能发动。融合怪兽卡决定的包含墓地的这张卡的融合素材怪兽从自己的手卡·场上·墓地用喜欢的顺序回到持有者卡组下面，把那1只融合怪兽从额外卡组融合召唤。'),
(38436986, 'Tearlaments Metanoise', '泪冠哀歌・作响的异界爪音', '壱世壊に軋む爪音', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上有「珠泪哀歌族」怪兽或者「维萨斯-斯塔弗罗斯特」存在的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽变成里侧守备表示。那之后，从卡组把1只「珠泪哀歌族」怪兽送去墓地。 ②：这张卡被效果送去墓地的场合，以自己墓地1只「珠泪哀歌族」怪兽为对象才能发动。那只怪兽加入手卡。'),
(34225426, 'Tearlaments Perlegia', '嫋嫋泪冠哀歌姬的壹世坏', '嫋々たる漣歌姫の壱世壊', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上的融合怪兽以及「珠泪哀歌族」怪兽的攻击力上升500。 ②：水族「珠泪哀歌族」怪兽被效果送去自己墓地的场合才能发动。从卡组把1只4星以下的水族怪兽送去墓地。这个效果把「珠泪哀歌族」怪兽以外的怪兽送去墓地的场合，这个回合，自己不能把这个效果送去墓地的卡以及那些同名卡的效果发动。'),
(73956664, 'Tearlaments Reinoheart', '泪冠哀歌・雷诺哈忒', 'ティアラメンツ・レイノハート', 'Effect Monster', 'Warrior', 'WATER', 4, 1500, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「珠泪哀歌族·雷诺哈特」以外的1只「珠泪哀歌族」怪兽送去墓地。 ②：这张卡被效果送去墓地的场合才能发动。这张卡特殊召唤，从自己手卡选1张「珠泪哀歌族」卡送去墓地。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(84330567, 'Tearlaments Rulkallos', '泪冠哀歌・露露卡洛斯', 'ティアラメンツ・ルルカロス', 'Fusion Monster', 'Aqua', 'WATER', 8, 3000, 2500, '「珠泪哀歌族·水仙女人鱼」＋「珠泪哀歌族」怪兽 这个卡名的②③的效果1回合各能使用1次。 ①：这张卡以外的自己的水族怪兽不会被战斗破坏。 ②：包含把怪兽特殊召唤效果的效果由对方发动时才能发动。那个发动无效并破坏。那之后，从手卡以及自己场上的表侧表示的卡之中选1张「珠泪哀歌族」卡送去墓地。 ③：融合召唤的这张卡被效果送去墓地的场合才能发动。这张卡特殊召唤。'),
(572850, 'Tearlaments Scheiren', '泪冠哀歌・赛莲', 'ティアラメンツ・シェイレーン', 'Effect Monster', 'Aqua', 'DARK', 4, 1800, 1300, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。这张卡从手卡特殊召唤，从自己手卡选1只怪兽送去墓地。那之后，从自己卡组上面把3张卡送去墓地。 ②：这张卡被效果送去墓地的场合才能发动。融合怪兽卡决定的包含墓地的这张卡的融合素材怪兽从自己的手卡·场上·墓地用喜欢的顺序回到持有者卡组下面，把那1只融合怪兽从额外卡组融合召唤。'),
(6767771, 'Tearlaments Scream', '泪冠哀歌・劈斩的刺耳弦声', '壱世壊を劈く弦声', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：场上有怪兽召唤·特殊召唤的场合，若自己场上有「珠泪哀歌族」怪兽或者「维萨斯-斯塔弗罗斯特」存在则能发动。从自己卡组上面把3张卡送去墓地。这个回合，对方场上的怪兽的攻击力下降500。 ②：这张卡被效果送去墓地的场合才能发动。从卡组把1张「珠泪哀歌族」陷阱卡加入手卡。'),
(74920585, 'Tearlaments Sulliek', '泪冠哀歌・奏鸣的摧花悲唱', '壱世壊に奏でる哀唱', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「珠泪哀歌族」怪兽或者「维萨斯-斯塔弗罗斯特」存在的场合，以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果无效。那之后，选自己场上1只怪兽送去墓地。 ②：这张卡被效果送去墓地的场合才能发动。从卡组把1只「珠泪哀歌族」怪兽加入手卡。'),
(68392533, 'Telekinetic Charging Cell', '念动增幅装置', '念動増幅装置', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '念动力族怪兽才能装备。为装备怪兽的效果发动而支付的基本分变成不需要。装备怪兽被破坏让这张卡送去墓地时，可以支付1000基本分让这张卡回到手卡。'),
(28741524, 'Telekinetic Power Well', '念动收集机', '念動収集機', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '自己墓地存在的2星以下的念动力族怪兽任意数量特殊召唤。那之后，自己受到这个效果特殊召唤的怪兽等级合计×300的数值的伤害。'),
(84847656, 'Telekinetic Shocker', '念动攻击者', 'テレキアタッカー', 'Effect Monster', 'Psychic', 'EARTH', 4, 1700, 700, '念动力族怪兽被破坏的场合，可以支付500基本分作为代替把这张卡破坏。'),
(23323812, 'Telepathic Power', '念导力', '念導力', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的念动力族怪兽被对方怪兽的攻击破坏的场合才能发动。那个时候进行攻击的1只对方怪兽破坏，自己基本分回复那个攻击力的数值。'),
(6795211, 'Teleport', '物体显形', 'アポート', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，只有对方场上才有怪兽存在的场合，支付800基本分才能发动。从手卡把1只念动力族怪兽特殊召唤。'),
(36494597, 'Teleport Fusion', '瞬移结合', 'テレポート・フュージョン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段才能发动。自己的场上·墓地的念动力族怪兽作为融合素材除外，把1只念动力族融合怪兽融合召唤。 ②：从额外卡组特殊召唤的自己场上的表侧表示的念动力族怪兽被战斗·效果破坏的场合，把墓地的这张卡除外，以自己的除外状态的1只念动力族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(42822433, 'Tellarknight Altairan', '星骑士 天鹰阿尔提亚', '星騎士 アルテア', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1700, 1300, '这个卡名在规则上也当作「星圣」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤的场合，以最多有自己场上的光·暗属性超量怪兽数量的场上的卡为对象才能发动。那些卡破坏。 ②：自己场上有「星骑士 牛郎星」以外的「星骑士」、「星圣」怪兽特殊召唤的场合才能发动。这张卡从墓地特殊召唤。这个回合，自己不用超量怪兽不能攻击宣言。'),
(58858807, 'Tellarknight Constellar Caduceus', '星骑士 星圣 卡多克乌斯', '星騎士 セイクリッド・カドケウス', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2500, 1650, '4星怪兽×2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡超量召唤的场合，以自己墓地的「星骑士」、「星圣」卡各最多1张为对象才能发动。那些卡加入手卡。 ②：从手卡·卡组把1只「星骑士」、「星圣」怪兽除外，把这张卡1个超量素材取除才能发动。除外的怪兽的自身的召唤成功时发动的效果适用。'),
(32289031, 'Tellarknight Constellar Delteros', '星骑士 星圣 德塔特洛斯', '星騎士 セイクリッド・デルタテロス', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2500, 2500, '4星怪兽×3只以上 ①：对方不能把自己场上的5阶以上的「星骑士」、「星圣」超量怪兽作为效果的对象。 ②：1回合1次，把这张卡1个超量素材取除才能发动。从卡组把1只「星骑士」、「星圣」怪兽加入手卡。那之后，可以进行1只光属性怪兽的召唤。 ③：这张卡从场上以外送去墓地的场合才能发动。自己的手卡·除外状态的1只「星骑士」、「星圣」怪兽特殊召唤。'),
(60700283, 'Tellarknight Cygnian', '星骑士 天鹅丘格尼', '星騎士 キュグニ', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1500, 1000, '这个卡名在规则上也当作「星圣」卡使用。这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤的场合才能发动。从卡组把1只「星骑士」、「星圣」怪兽加入手卡。 ②：以自己场上1只其他的光属性怪兽为对象才能发动。那只怪兽和这张卡的等级上升1星。 ③：以怪兽3只以上为素材的「星骑士」超量怪兽超量召唤的场合，这张卡可以作为2只数量的超量素材。'),
(65236257, 'Tellarknight Genesis', '创星骑士的因子', '創星の因子', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：选这张卡以外的自己场上的「星骑士」卡数量的场上的魔法·陷阱卡破坏。'),
(79210531, 'Tellarknight Lyran', '星骑士 天琴琉拉', '星騎士 リュラ', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1200, 1600, '这个卡名在规则上也当作「星圣」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「星骑士 织女星」以外的「星骑士」、「星圣」怪兽召唤的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·反转召唤·特殊召唤的场合才能发动。从卡组把1张「星骑士」魔法卡加入手卡。'),
(18326736, 'Tellarknight Ptolemaeus', '守星骑士 托勒密', '星守の騎士 プトレマイオス', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 550, 2600, '4星怪兽×2只以上 ①：可以把这张卡的超量素材的以下数量取除，那个效果发动。 ●3个：自己·对方回合可以发动（同一连锁上最多1次）。除「No.」怪兽外的比这张卡阶级高1阶的1只超量怪兽在自己场上的这张卡上面重叠当作超量召唤从额外卡组特殊召唤。 ●7个：自己主要阶段才能发动。下次的对方回合跳过。 ②：自己·对方的结束阶段才能发动。从额外卡组把1张「星辉士」卡作为这张卡的超量素材。'),
(19280589, 'Tellus the Little Angel', '小天使特勒斯', '小天使テルス', 'Effect Monster', 'Fairy', 'LIGHT', 3, 500, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡从怪兽区域送去墓地的场合才能发动。在自己场上把1只「忒勒斯的羽翼衍生物」（天使族·光·1星·攻/守0）特殊召唤。 ②：自己场上有「忒勒斯的羽翼衍生物」存在的场合，把墓地的这张卡和手卡1张魔法卡除外才能发动。在自己场上把2只「忒勒斯的羽翼衍生物」特殊召唤。这个效果的发动后，直到回合结束时自己不是从手卡中不能把怪兽特殊召唤。'),
(24431911, 'Tellusion the Magna Warrior', '磁石之战士 大地机翁', '磁石の戦士マグネット・テルスリオン', 'Effect Monster', 'Rock', 'EARTH', 8, 2500, 2500, '这张卡不能通常召唤。把自己的手卡·场上（表侧表示）·墓地的「磁石战士Σ+」「磁石战士Σ-」各1只除外的场合才能从墓地特殊召唤。 ①：1回合1次，对方把效果发动时，以对方场上1只怪兽为对象才能发动。那只怪兽破坏。以地属性怪兽为对象发动的场合，也能作为代替而得到那只怪兽的控制权。 ②：对方回合，把这张卡解放才能发动。自己的除外状态的2只「磁石战士Σ」怪兽特殊召唤。'),
(87608852, 'Temperance of Prophecy', '魔导召唤士 坦佩尔', '魔導召喚士 テンペル', 'Effect Monster', 'Spellcaster', 'EARTH', 3, 1000, 1000, '自己把名字带有「魔导书」的魔法卡发动的自己回合的主要阶段时，把这张卡解放才能发动。从卡组把1只光属性或者暗属性的魔法师族·5星以上的怪兽特殊召唤。这个效果发动的回合，自己不能把其他的5星以上的怪兽特殊召唤。'),
(63101919, 'Tempest Magician', '暴风魔术师', 'マジックテンペスター', 'Synchro Monster', 'Spellcaster', 'DARK', 6, 2200, 1400, '调整＋调整以外的魔法师族怪兽1只以上 这张卡同调召唤成功时，给这张卡放置1个魔力指示物。1回合1次，可以把自己手卡任意数量送去墓地，那个数量的魔力指示物给自己场上表侧表示存在的怪兽放置。此外，可以把场上存在的魔力指示物全部取除，给与对方基本分那个数量×500的数值的伤害。'),
(89399912, 'Tempest, Dragon Ruler of Storms', '岚征龙－暴风', '嵐征竜－テンペスト', 'Effect Monster', 'Dragon', 'WIND', 7, 2400, 2200, '这个卡名的①～④的效果1回合只能有1次使用其中任意1个。 ①：从手卡把这张卡和1只风属性怪兽丢弃去墓地才能发动。从卡组把1只龙族怪兽加入手卡。 ②：把2只龙族或风属性的怪兽从自己的手卡·墓地除外才能发动。这张卡从手卡·墓地特殊召唤。 ③：这张卡特殊召唤的场合，对方结束阶段发动。这张卡回到手卡。 ④：这张卡被除外的场合才能发动。从卡组把1只龙族·风属性怪兽加入手卡。'),
(24521325, 'Template Skipper', '模板弹涂鱼', 'テンプレート・スキッパー', 'Effect Monster', 'Cyberse', 'DARK', 1, NULL, NULL, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以从手卡往作为电子界族连接怪兽所连接区的自己场上特殊召唤。 ②：自己主要阶段才能发动。从自己的手卡·墓地把1只电子界族怪兽除外。这个回合连接召唤的场合，这张卡可以作为这个效果除外的怪兽的同名卡来成为连接素材。'),
(732302, 'Temple of Skulls', '骷髅寺院', '髑髏の寺院', 'Normal Monster', 'Zombie', 'DARK', 4, 900, 1300, '全部由骷髅和骨头建立而成的寺院。会吸收接近的人的灵魂。'),
(29762407, 'Temple of the Kings', '王家的神殿', '王家の神殿', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己可以把1张陷阱卡在盖放的回合发动。 ②：把自己场上的表侧表示的1只「圣兽 塞勒凯特」和这张卡送去墓地才能发动。手卡·卡组1只怪兽或者额外卡组1只融合怪兽特殊召唤。'),
(92481084, 'Temple of the Mind''s Eye', '心眼之祭殿', '心眼の祭殿', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，自己或者对方受到战斗伤害的场合，那个数值变成1000。'),
(53819808, 'Temple of the Six', '六武院', '六武院', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '每次名字带有「六武众」的怪兽召唤·特殊召唤，给这张卡放置1个武士道指示物。对方场上表侧表示存在的怪兽的攻击力下降这张卡放置的武士道指示物数量×100的数值。'),
(91468551, 'Temple of the Sun', '太阳的祭坛', '太陽の祭壇', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，自己场上表侧表示存在的从墓地特殊召唤的怪兽的攻击力上升300。'),
(86304179, 'Tempura of Fortune - EBI', '运否的天赋罗－EBI', '運否の天賦羅－EBI', 'Pendulum Normal Monster', 'Aqua', 'FIRE', 3, 1600, NULL, '走进话题火爆的江户前线(EDO－FRONT)。这里的天赋罗不仅尺度之大不用多说，其富有美感的造型还甚至享有「金赋罗」的异名。港内虽然满是最新锐设备和异文化感，却又飘散着莫名感到怀念的醇香，时而劈啪作响的轻快音色令人心都酥炸了。期盼已久的天赋罗，可惜今天因为周边空域要变天的影响而一律不入港……。虽说是运气差，但连这后面的预定也不得不就此取消。正因为满心期待了1年才更感到特别遗憾，不过就这次的应对态度来说，我认为给3颗星是妥当的。'),
(52558805, 'Temtempo the Percussion Djinn', '太鼓魔人 咚咚拍子', '太鼓魔人テンテンテンポ', 'XYZ Monster', 'Fiend', 'EARTH', 3, 1700, 1000, '3星怪兽×2 1回合1次，把这张卡1个超量素材取除，选择对方场上1只超量怪兽才能发动。把选择的怪兽1个超量素材取除，自己场上的全部名字带有「魔人」的超量怪兽的攻击力上升500。这个效果在对方回合也能发动。'),
(10000, 'Ten Thousand Dragon', '宝石骑士・绿龙晶', 'ジェムナイト・セラフィ', 'Effect Monster', 'Dragon', 'DARK', 10, -1, -1, '这张卡不能通常召唤。把攻击力合计和守备力合计的总计直到10000以上的自己场上的怪兽解放的场合才能特殊召唤。 ①：这个方法特殊召唤的这张卡的攻击力·守备力变成10000。'),
(33609262, 'Tenacity of the Monarchs', '帝王的深怨', '帝王の深怨', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把手卡1只攻击力2400/守备力1000的怪兽或者1只攻击力2800/守备力1000的怪兽给对方观看才能发动。从卡组把「帝王的深怨」以外的1张「帝王」魔法·陷阱卡加入手卡。'),
(9597987, 'Tenchi Kaimei', '天地晦冥', '天地晦冥', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「忍法」卡使用。 ①：自己的「忍者」怪兽给与对方战斗伤害时，以对方场上1张卡为对象才能发动。那张卡破坏。 ②：场地区域的表侧表示的这张卡因对方的效果从场上离开，被送去墓地的场合或者被除外的场合，以自己墓地的「忍者」怪兽任意数量为对象才能发动（同名卡最多1张）。那些怪兽里侧守备表示特殊召唤。'),
(57935140, 'Tenderness', '温柔天使', 'テンダネス', 'Normal Monster', 'Fairy', 'LIGHT', 3, 700, 1400, '为恋人们献上祝福的可爱天使。'),
(4103668, 'Tengu, the Winged Mayakashi', '翼之魔妖－天狗', '翼の魔妖－天狗', 'Synchro Monster', 'Zombie', 'WIND', 7, 2600, 1500, '调整＋调整以外的怪兽1只以上 这个卡名的②③的效果1回合各能使用1次。 ①：「翼之魔妖-天狗」在自己场上只能有1只表侧表示存在。 ②：这张卡在墓地存在，原本等级是9星的自己的同调怪兽被战斗或者对方的效果破坏的场合才能发动。从自己墓地把1只其他的不死族怪兽除外，这张卡特殊召唤。 ③：这张卡从墓地的特殊召唤成功的场合才能发动。选对方场上1张魔法·陷阱卡破坏。'),
(41589166, 'Tenkabito Shien', '天下人 紫炎', '天下人 紫炎', 'Effect Monster', 'Pyro', 'FIRE', 4, 1500, 1000, '这张卡不受陷阱卡的效果影响。'),
(33837653, 'Tenma the Sky Star', '天升星 天马', '天昇星テンマ', 'Effect Monster', 'Warrior', 'LIGHT', 5, 2100, 1000, '这个卡名的②的效果1回合只能使用1次。 ①：在只有对方场上才有怪兽存在的场合或者在自己场上有地属性怪兽存在的场合，这张卡可以不用解放作召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从手卡把1只战士族·地属性·5星怪兽特殊召唤。 ③：1回合1次，自己场上的战士族怪兽为对象的对方的效果发动时才能发动。这张卡的攻击力下降500，那个发动无效并破坏。'),
(90122655, 'Tenmataitei', '天魔大帝', '天魔大帝', 'Effect Monster', 'Warrior', 'DARK', 5, 2400, 1000, '①：只要这张卡在怪兽区域存在，对方不能对应通常召唤的怪兽的效果的发动把魔法·陷阱·怪兽的效果发动。'),
(91810826, 'Tenpai Dragon Chundra', '天杯龙 红中龙', '天盃龍チュンドラ', 'Tuner Monster', 'Dragon', 'FIRE', 4, 1500, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有龙族·炎属性怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：怪兽进行战斗的伤害步骤开始时才能发动。除「天杯龙 中龙」外的1只4星以下的龙族·炎属性怪兽从卡组特殊召唤。 ③：1回合1次，自己·对方的战斗阶段才能发动。用包含这张卡的自己场上的怪兽为素材进行同调召唤。'),
(65326118, 'Tenpai Dragon Fadra', '天杯龙 绿发龙', '天盃龍ファドラ', 'Effect Monster', 'Dragon', 'FIRE', 3, 1600, 1000, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合或者怪兽进行战斗的伤害步骤开始时，以自己墓地1只4星以下的龙族·炎属性怪兽为对象才能发动。那只怪兽特殊召唤。 ②：只要这张卡在怪兽区域存在，自己的龙族·炎属性怪兽不会被战斗破坏。 ③：1回合1次，自己·对方的战斗阶段才能发动。用包含这张卡的自己场上的怪兽为素材进行同调召唤。'),
(23657016, 'Tenpai Dragon Genroku', '幻禄天杯龙', '幻禄の天盃龍', 'Effect Monster', 'Dragon', 'FIRE', 3, NULL, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用抽卡以外的方法加入手卡的场合才能发动。这张卡当作调整使用特殊召唤。那之后，可以让这张卡的等级上升1星。 ②：自己·对方回合，把这张卡解放才能发动。从卡组把「幻禄之天杯龙」以外的1只「天杯龙」怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是龙族怪兽不能特殊召唤。'),
(39931513, 'Tenpai Dragon Paidra', '天杯龙 白板龙', '天盃龍パイドラ', 'Effect Monster', 'Dragon', 'FIRE', 3, 1700, 1000, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组选1张「灿幻」魔法·陷阱卡加入手卡或在自己场上盖放。 ②：只要这张卡在怪兽区域存在，自己的龙族·炎属性怪兽的战斗发生的对自己的战斗伤害变成0。 ③：1回合1次，自己·对方的战斗阶段才能发动。用包含这张卡的自己场上的怪兽为素材进行同调召唤。'),
(56322832, 'Tensei Ryu-Ge Anva', '转惺龙华－暗轮巴王', '転惺竜華－闇巴', 'Pendulum Effect Monster', 'Dragon', 'DARK', 10, 3000, 2100, '这个卡名的①②③的怪兽效果1回合各能使用1次。 ①：把「转惺龙华-暗巴」以外的自己的手卡·场上1只「龙华」怪兽解放才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤的场合，以场上1张卡为对象才能发动。那张卡破坏。 ③：这张卡被破坏的场合才能发动。自己的卡组·墓地·除外状态的1张「龙华」永续魔法·永续陷阱卡在自己场上表侧表示放置。'),
(59563768, 'Tenshin', '转身天使', '転身テンシーン', 'Effect Monster', 'Fairy', 'LIGHT', 2, 800, 100, '这张卡的攻击力上升自己场上表侧表示存在的2星怪兽数量×400的数值。'),
(60715406, 'Tentacle Plant', '藤蔓植物', 'テンタクル・プラント', 'Normal Monster', 'Plant', 'WATER', 2, 500, 600, '当附近有会动的东西时，就会伸出蓝色的丝线攻击。'),
(98159737, 'Tenyi Spirit - Adhara', '天威龙－阿靼剌', '天威龍－アーダラ', 'Tuner Monster', 'Wyrm', 'EARTH', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上没有效果怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己场上有效果怪兽以外的表侧表示怪兽存在的场合，把手卡·墓地的这张卡除外，以这张卡以外的除外的1只自己的幻龙族怪兽为对象才能发动。那只怪兽加入手卡。'),
(87052196, 'Tenyi Spirit - Ashuna', '天威龙－阿舒那', '天威龍－アシュナ', 'Effect Monster', 'Wyrm', 'LIGHT', 7, 1600, 2600, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上没有效果怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己场上有效果怪兽以外的表侧表示怪兽存在的场合，把手卡·墓地的这张卡除外才能发动。从卡组把「天威龙-宽恕蟠龙」以外的1只「天威」怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是幻龙族怪兽不能特殊召唤。'),
(60942444, 'Tenyi Spirit - Mapura', '天威龙－马尼剌', '天威龍－マニラ', 'Effect Monster', 'Wyrm', 'FIRE', 4, 600, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上没有效果怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：效果怪兽以外的自己场上的表侧表示怪兽为对象的对方的魔法·陷阱·怪兽的效果发动时，把手卡·墓地的这张卡除外才能发动。那个发动无效并破坏。'),
(73121813, 'Tenyi Spirit - Mula Adhara', '天威龙－穆剌阿靼剌', '天威龍－ムーラ・アーダラ', 'Synchro Monster', 'Wyrm', 'LIGHT', 8, 3000, NULL, '调整＋调整以外的怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡同调召唤的场合，若自己的墓地·除外状态的幻龙族怪兽2只以上存在则能发动。从卡组把1张场地魔法卡加入手卡。 ②：只要场上有效果怪兽以外的表侧表示怪兽存在，这张卡得到以下效果。 ●这张卡不会被对方的效果破坏。 ●对方不能把这张卡作为效果的对象。 ●这张卡在同1次的战斗阶段中可以作2次攻击。'),
(97036149, 'Tenyi Spirit - Nahata', '天威龙－纳哈塔', '天威龍－ナハタ', 'Effect Monster', 'Wyrm', 'WIND', 4, 800, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上没有效果怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：效果怪兽以外的自己的表侧表示怪兽在和对方的表侧表示怪兽进行战斗的攻击宣言时，把手卡·墓地的这张卡除外才能发动。那只对方怪兽的攻击力直到回合结束时下降1500。'),
(38030232, 'Tenyi Spirit - Sahasrara', '天威龙－萨哈司剌剌', '天威龍－サハスラーラ', 'Link Monster', 'Wyrm', 'LIGHT', NULL, 3000, NULL, '幻龙族怪兽2只以上 这个卡名的②的效果1回合只能使用1次。 ①：自己场上有效果怪兽以外的表侧表示怪兽存在的场合，对方不能把场上的效果怪兽作为攻击对象，也不能作为效果的对象。 ②：以对方场上1只效果怪兽为对象才能发动。在自己场上把1只「天威龙衍生物」（幻龙族·光·4星·攻?/守0）特殊召唤。这衍生物的攻击力变成和作为对象的怪兽的原本攻击力相同。这个效果在对方回合也能发动。'),
(24557335, 'Tenyi Spirit - Shthana', '天威龙－休塔纳', '天威龍－シュターナ', 'Effect Monster', 'Wyrm', 'WATER', 4, 400, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上没有效果怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：效果怪兽以外的自己场上的表侧表示怪兽被战斗·效果破坏的场合，把手卡·墓地的这张卡除外，以那1只破坏的怪兽为对象才能发动。那只怪兽特殊召唤。那之后，可以选对方场上1只怪兽破坏。');